import { snapshotPersistenceInput } from './input-snapshot.mjs';
import { and, eq, sql } from 'drizzle-orm';
import type { IdentityDatabase } from './identity-database.js';
import {
  ApplicationSessionNotFoundError,
  type ApplicationSessionRepository,
} from '../../application/ports/application-session-repository.js';
import {
  absoluteExpiryFromIssuedAt,
  SESSION_CREDENTIAL_BYTES,
  SESSION_VERIFIER_VERSION,
  type ApplicationSessionRecord,
} from '../../domain/application-session.js';
import {
  applicationSessions,
  identities,
  type ApplicationSessionRow,
} from './schema.js';

export class PostgresApplicationSessionRepository
  implements ApplicationSessionRepository
{
  constructor(private readonly db: IdentityDatabase) {}

  async create(input: {
    readonly id: string;
    readonly identityId: string;
    readonly credential: {
      readonly verifierVersion: 'v1';
      readonly verifier: Buffer;
    };
    readonly now: Date;
  }): Promise<ApplicationSessionRecord> {
    input = snapshotPersistenceInput(input);
    if (input.id.trim().length === 0) {
      throw new RangeError('ApplicationSessionId must be non-blank');
    }

    return this.db.transaction(async (tx) => {
      const lock = await tx.execute(
        sql`select "status" from "identity_identities" where "id" = ${input.identityId} for update`,
      );
      if (lock.rows[0]?.status !== 'ACTIVE') {
        throw new ApplicationSessionNotFoundError();
      }

      const [created] = await tx
        .insert(applicationSessions)
        .values({
          id: input.id,
          identityId: input.identityId,
          status: 'ACTIVE',
          verifierVersion: input.credential.verifierVersion,
          credentialVerifier: input.credential.verifier,
          issuedAt: input.now,
          absoluteExpiresAt: absoluteExpiryFromIssuedAt(input.now),
          lastUsedAt: input.now,
          createdAt: input.now,
          updatedAt: input.now,
        })
        .returning();

      if (!created) throw new Error('ApplicationSession insert returned no row');
      return mapSession(created);
    });
  }

  async getById(input: {
    readonly id: string;
    readonly identityId: string;
  }): Promise<ApplicationSessionRecord | null> {
    input = snapshotPersistenceInput(input);
    const [row] = await this.db
      .select()
      .from(applicationSessions)
      .where(
        and(
          eq(applicationSessions.id, input.id),
          eq(applicationSessions.identityId, input.identityId),
        ),
      )
      .limit(1);
    return row ? mapSession(row) : null;
  }

  async revoke(input: {
    readonly id: string;
    readonly identityId: string;
    readonly now: Date;
  }): Promise<ApplicationSessionRecord> {
    input = snapshotPersistenceInput(input);
    return (await this.revokeWithOutcome(input)).session;
  }

  async revokeWithOutcome(input: {
    readonly id: string;
    readonly identityId: string;
    readonly now: Date;
  }): Promise<{ session: ApplicationSessionRecord; transitioned: boolean }> {
    input = snapshotPersistenceInput(input);
    return this.db.transaction(async tx => {
      const [current] = await tx.select().from(applicationSessions).where(and(
        eq(applicationSessions.id, input.id), eq(applicationSessions.identityId, input.identityId),
      )).limit(1).for('update');
      if (!current) throw new ApplicationSessionNotFoundError();
      if (current.status !== 'ACTIVE') return { session: mapSession(current), transitioned: false };
      const [updated] = await tx.update(applicationSessions).set({
        status: 'REVOKED', revokedAt: input.now, updatedAt: input.now,
      }).where(and(eq(applicationSessions.id, input.id), eq(applicationSessions.identityId, input.identityId), eq(applicationSessions.status, 'ACTIVE'))).returning();
      if (!updated) throw new Error('Locked ApplicationSession transition returned no row');
      return { session: mapSession(updated), transitioned: true };
    });
  }

  async authenticateByVerifier(input: {
    readonly verifierVersion: 'v1';
    readonly verifier: Buffer;
    readonly now: Date;
  }): Promise<ApplicationSessionRecord | null> {
    input = snapshotPersistenceInput(input);
    if (
      input.verifierVersion !== SESSION_VERIFIER_VERSION ||
      !Buffer.isBuffer(input.verifier) || input.verifier.length !== SESSION_CREDENTIAL_BYTES ||
      !(input.now instanceof Date) || !Number.isFinite(input.now.getTime())
    ) return null;
    return this.db.transaction(async (tx) => {
      const [candidate] = await tx
        .select({
          id: applicationSessions.id,
          identityId: applicationSessions.identityId,
        })
        .from(applicationSessions)
        .where(
          and(
            eq(applicationSessions.verifierVersion, input.verifierVersion),
            eq(applicationSessions.credentialVerifier, input.verifier),
          ),
        )
        .limit(1);
      if (!candidate) return null;

      const identityLock = await tx.execute(
        sql`select "status" from "identity_identities" where "id" = ${candidate.identityId} for update`,
      );
      if (identityLock.rows[0]?.status !== 'ACTIVE') return null;

      const [updated] = await tx
        .update(applicationSessions)
        .set({ lastUsedAt: input.now, updatedAt: input.now })
        .where(
          and(
            eq(applicationSessions.id, candidate.id),
            eq(applicationSessions.identityId, candidate.identityId),
            eq(applicationSessions.status, 'ACTIVE'),
            validSessionTimelineAt(input.now),
            sql`${input.now} < ${applicationSessions.absoluteExpiresAt}`,
            sql`${input.now} < ${applicationSessions.lastUsedAt} + interval '30 minutes'`,
          ),
        )
        .returning();

      return updated ? mapSession(updated) : null;
    });
  }
}

function validSessionTimelineAt(now: Date) {
  // Match the domain's temporal checks before successful authentication can
  // refresh last use. Denial never writes lifecycle state; a clock rollback
  // must not reach the monotonic last-use trigger and raise a database error.
  return sql`(
    isfinite(${applicationSessions.issuedAt})
    AND isfinite(${applicationSessions.absoluteExpiresAt})
    AND isfinite(${applicationSessions.lastUsedAt})
    AND ${applicationSessions.absoluteExpiresAt} = ${applicationSessions.issuedAt} + interval '12 hours'
    AND ${applicationSessions.lastUsedAt} >= ${applicationSessions.issuedAt}
    AND ${applicationSessions.lastUsedAt} <= ${applicationSessions.absoluteExpiresAt}
    AND ${now} >= ${applicationSessions.issuedAt}
    AND ${now} >= ${applicationSessions.lastUsedAt}
  )`;
}

function mapSession(row: ApplicationSessionRow): ApplicationSessionRecord {
  return {
    id: row.id,
    identityId: row.identityId,
    status: row.status,
    verifierVersion: 'v1',
    verifier: row.credentialVerifier,
    issuedAt: row.issuedAt,
    absoluteExpiresAt: row.absoluteExpiresAt,
    lastUsedAt: row.lastUsedAt,
    revokedAt: row.revokedAt,
    expiredAt: row.expiredAt,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

import { snapshotPersistenceInput } from './input-snapshot.mjs';
import { and, eq, sql } from 'drizzle-orm';
import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import {
  assertValidCredential,
  type CredentialRecord,
  type CredentialType,
} from '../../domain/credential.js';
import * as identitySchema from './schema.js';
import * as credentialSchema from './credential-schema.js';
import { credentials, type CredentialRow } from './credential-schema.js';
import type { CredentialRepository } from '../../application/ports/credential-repository.js';

type DbSchema = typeof identitySchema & typeof credentialSchema;

export class PostgresCredentialRepository implements CredentialRepository {
  constructor(private readonly db: NodePgDatabase<DbSchema>) {}

  async create(input: {
    readonly id: string;
    readonly identityId: string;
    readonly credentialType: CredentialType;
    readonly passwordHash: string | null;
    readonly now: Date;
  }): Promise<CredentialRecord> {
    input = snapshotPersistenceInput(input);
    assertValidCredential(input);
    return this.db.transaction(async (tx) => {
      // IDN-14: Identity must be ACTIVE to receive credentials
      const lock = await tx.execute(
        sql`select "status" from "identity_identities" where "id"=${input.identityId} for update`,
      );
      if (lock.rows[0]?.status !== 'ACTIVE') {
        throw new Error('authoritative Identity must be ACTIVE');
      }
      const [row] = await tx
        .insert(credentials)
        .values({
          id: input.id,
          identityId: input.identityId,
          credentialType: input.credentialType,
          passwordHash: input.passwordHash,
          createdAt: input.now,
          updatedAt: input.now,
        })
        .returning();
      if (!row) throw new Error('Credential insert returned no row');
      return map(row);
    });
  }

  async findById(input: { readonly id: string; readonly identityId: string }): Promise<CredentialRecord | null> {
    input = snapshotPersistenceInput(input);
    const [row] = await this.db
      .select()
      .from(credentials)
      .where(and(eq(credentials.id, input.id), eq(credentials.identityId, input.identityId)))
      .limit(1);
    return row ? map(row) : null;
  }

  async revoke(input: { readonly id: string; readonly identityId: string; readonly now: Date }): Promise<CredentialRecord | null> {
    input = snapshotPersistenceInput(input);
    const [row] = await this.db
      .update(credentials)
      .set({ revokedAt: input.now, updatedAt: input.now })
      .where(
        and(
          eq(credentials.id, input.id),
          eq(credentials.identityId, input.identityId),
          sql`${credentials.revokedAt} IS NULL`,
        ),
      )
      .returning();
    return row ? map(row) : null;
  }

  async listByIdentity(input: { readonly identityId: string }): Promise<CredentialRecord[]> {
    input = snapshotPersistenceInput(input);
    const rows = await this.db
      .select()
      .from(credentials)
      .where(eq(credentials.identityId, input.identityId));
    return rows.map(map);
  }
}

function map(row: CredentialRow): CredentialRecord {
  return {
    id: row.id,
    identityId: row.identityId,
    credentialType: row.credentialType,
    passwordHash: row.passwordHash,
    revokedAt: row.revokedAt,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

